-- changeset martini:catalog-original-seed
INSERT INTO catalog_entries (kind, slug, payload) VALUES
    ('recipes', 'flan', '{"published":true,"category":"Postres","id":"flan","title":"Flan con dulce de leche","description":"Un postre clásico, suave y cremoso, para acompañar con dulce de leche.","duration":"75 min + 4 h de frío","servings":"6 porciones","ingredients":["5 huevos","500 ml de leche","100 g de azúcar para el flan","100 g de azúcar para el caramelo","1 cucharadita de esencia de vainilla","Dulce de leche para servir"],"steps":["Precalentá el horno a 160 °C. Calentá el azúcar del caramelo a fuego bajo hasta que se dore y distribuí en la flanera.","Mezclá los huevos con el azúcar sin incorporar demasiado aire. Agregá la leche y la vainilla.","Verté la mezcla en la flanera. Colocala en una fuente con agua caliente hasta la mitad del molde.","Horneá a baño María entre 50 y 60 minutos, hasta que los bordes estén firmes y el centro apenas se mueva.","Dejá enfriar y refrigerá al menos 4 horas. Desmoldá y serví con dulce de leche."],"videoTitle":"Técnica de flan clásico · Preppy Kitchen (en inglés)","videoUrl":"https://www.youtube.com/watch?v=d7_CTU4HXEY"}'),
    ('recipes', 'salsa-parrilla', '{"published":true,"category":"Salsas","id":"salsa-parrilla","title":"Salsa especial para la parrilla","description":"Un chimichurri fresco para acompañar carnes y verduras a la parrilla.","duration":"10 min + reposo","servings":"1 frasco pequeño","ingredients":["1 taza de perejil picado","2 dientes de ajo picados","1 cucharada de orégano","1 cucharadita de ají molido","100 ml de aceite","3 cucharadas de vinagre","Sal y pimienta a gusto"],"steps":["Lavá y secá el perejil. Picá finamente junto con los dientes de ajo.","Mezclá el perejil, ajo, orégano y ají molido en un recipiente limpio.","Incorporá el vinagre y el aceite. Condimentá con sal y pimienta.","Dejá reposar 30 minutos en la heladera para integrar los sabores. Mezclá antes de servir."],"videoTitle":"Chimichurri · tutorial de referencia","videoUrl":"https://www.youtube.com/watch?v=jBvqHqGQhAY"}'),
    ('recipes', 'tarta-verduras', '{"published":true,"category":"Panadería y horneados","id":"tarta-verduras","title":"Tarta de verduras","description":"Una tarta casera con verduras salteadas y un relleno de huevo y queso.","duration":"55 min","servings":"6 porciones","ingredients":["1 tapa de masa para tarta","1 cebolla","1 zanahoria","1 zucchini","3 huevos","150 g de queso rallado","100 ml de crema","1 cucharada de aceite","Sal y pimienta a gusto"],"steps":["Precalentá el horno a 180 °C. Forrá una tartera con la masa y pinchá la base.","Picá la cebolla, rallá la zanahoria y cortá el zucchini en cubos pequeños.","Salteá las verduras con el aceite durante 10 minutos, hasta que se ablanden y se evapore el exceso de líquido. Dejá entibiar.","Batí los huevos con la crema y el queso. Agregá las verduras y condimentá.","Volcá el relleno sobre la masa y horneá 35 a 40 minutos, hasta que la base esté dorada y el relleno firme. Dejá reposar antes de cortar."],"videoTitle":"Quiche de verduras · Bruno Oteiza","videoUrl":"https://www.youtube.com/watch?v=O8J_rEbetXM"}'),
    ('learning', 'postres', '{"id":"postres","title":"Masterclass de postres","specialty":"Pastelería de vitrina","summary":"Organiza una producción de postres con una presentación consistente. Guía introductoria de demostración.","isVideo":false,"lessons":["Planificación: define porciones, tiempos y una lista de ingredientes antes de comenzar.","Mise en place: pesa ingredientes y prepara moldes y utensilios limpios.","Cocción: precalienta el horno y comprueba la textura antes de retirar cada preparación.","Presentación: utiliza porciones uniformes y una decoración sencilla.","Conservación: respeta la cadena de frío e identifica cada preparación con su fecha.","Costeo: divide el costo total de ingredientes por las porciones obtenidas."],"videoUrl":null,"published":true}'),
    ('learning', 'chocolate', '{"id":"chocolate","title":"Introducción a la chocolatería","specialty":"Chocolatería","summary":"Conoce los fundamentos para trabajar coberturas y comenzar a crear piezas de chocolate.","isVideo":false,"lessons":["Materia prima: distingue cobertura de chocolate y baños de repostería. Revisa siempre la ficha del fabricante.","Preparación: mantén moldes y utensilios secos; evita el contacto del chocolate con agua.","Templado: sigue la curva de temperaturas indicada para tu cobertura, usando un termómetro.","Moldeado: distribuye el chocolate de forma uniforme y elimina burbujas con golpes suaves.","Evaluación: comprueba brillo, textura y desmolde antes de producir una nueva tanda."],"videoUrl":null,"published":true}'),
    ('learning', 'hojaldre', '{"id":"hojaldre","title":"Primeros pasos en masas de hoja","specialty":"Masas de hoja","summary":"Una guía de organización del laminado para panaderías y emprendimientos.","isVideo":false,"lessons":["Preparación: pesa los ingredientes y trabaja en una superficie limpia y fresca.","Laminado: procura una consistencia similar entre masa y materia grasa.","Descanso: refrigera entre vueltas para relajar la masa y mantener capas definidas.","Horneo: corta piezas parejas y evita abrir el horno durante el desarrollo inicial."],"videoUrl":null,"published":true}'),
    ('learning', 'video-flan', '{"id":"video-flan","title":"Técnica de cocción a baño María","specialty":"Pastelería","summary":"Observa la preparación de un flan clásico y reconoce los puntos clave de una cocción suave.","isVideo":true,"lessons":["Prepara el molde y controla el nivel del agua.","Observa la textura del centro del flan al finalizar la cocción.","Deja enfriar y refrigerar antes de desmoldar."],"videoUrl":"https://www.youtube.com/watch?v=d7_CTU4HXEY","published":true}'),
    ('learning', 'video-quiche', '{"id":"video-quiche","title":"Rellenos para tartas saladas","specialty":"Productos de horneo","summary":"Video de referencia de Bruno Oteiza: preparación de una quiche de verduras.","isVideo":true,"lessons":["Cocina las verduras y elimina el exceso de humedad.","Distribuye el relleno de manera uniforme.","Hornea hasta que la masa esté dorada y el relleno firme."],"videoUrl":"https://www.youtube.com/watch?v=O8J_rEbetXM","published":true}');
